/**
 * Reject a confirmed selection (rectangle corners and anchor) that the
 * worksheet structure cannot render. Both the four corners and the anchor are
 * checked: `parseSelection` normalises the corners but keeps the anchor as
 * submitted, so checking only `r1..c2` would leave a hole (Issue #1 thread 1
 * comment #39).
 *
 * @param {SelectionRect} selection
 * @param {number} rowCount
 * @param {number} colCount
 * @returns {void}
 */
export function assertSelectionInBounds(selection, rowCount, colCount) {
  const outside =
    selection.r1 >= rowCount ||
    selection.r2 >= rowCount ||
    selection.c1 >= colCount ||
    selection.c2 >= colCount ||
    selection.anchor.row >= rowCount ||
    selection.anchor.col >= colCount;
  if (outside) {
    throw invalidBody(
      `Selection is outside the worksheet structure (${rowCount}x${colCount})`,
    );
  }
}

/**
 * Reject a cell that lies outside the worksheet structure. Shared by both
 * cell-writing entry points (`PUT .../cells` and the `PUT .../state` replay) so
 * the "no cell outside the reported structure" invariant has exactly one
 * implementation (contract v1.3 A-2, Issue #1 thread 1 comment #51).
 *
 * @param {number} row
 * @param {number} col
 * @param {number} rowCount
 * @param {number} colCount
 * @returns {void}
 */
export function assertCellWithinStructure(row, col, rowCount, colCount) {
  if (row >= rowCount || col >= colCount) {
    throw invalidBody(
      `Cell ${row},${col} is outside the worksheet structure (${rowCount}x${colCount})`,
    );
  }
}

/**
 * Parse a `POST .../rows|cols` body: `{index, count, side}` (contract endpoint
 * 8; Issue #4 comment #35 D-B1). `index` is the 0-based target row/column and
 * `side` is relative to it; the caller checks `index` against the current
 * structure because only it knows the worksheet dimensions.
 *
 * @param {unknown} body
 * @param {'row' | 'column'} axis
 * @returns {{ index: number, count: number, side: 'above' | 'below' | 'left' | 'right' }}
 */
export function parseInsertRequest(body, axis) {
  const obj = asObject(body);
  const index = asNonNegativeInt(obj.index, 'index');
  if (typeof obj.count !== 'number' || !Number.isInteger(obj.count) || obj.count < 1) {
    throw invalidBody('count must be a positive integer');
  }
  const sides = axis === 'row' ? ['above', 'below'] : ['left', 'right'];
  if (typeof obj.side !== 'string' || !sides.includes(obj.side)) {
    throw invalidBody(`side must be one of ${sides.join(', ')}`);
  }
  return {
    index,
    count: obj.count,
    side: /** @type {'above' | 'below' | 'left' | 'right'} */ (obj.side),
  };
}

/**
 * Parse a 0-based row/column index from a URL path parameter.
 *
 * @param {string} value
 * @returns {number}
 */
export function parseIndexParam(value) {
  if (!/^(0|[1-9][0-9]*)$/.test(value)) {
    throw invalidBody('index must be a non-negative integer');
  }
  return Number.parseInt(value, 10);
}

